CREATE TYPE public.account_role AS ENUM ('nurse', 'hospital', 'tourism');
CREATE TYPE public.gig_status AS ENUM ('draft', 'published', 'closed');
CREATE TYPE public.application_status AS ENUM ('applied', 'reviewing', 'qualified', 'interview', 'offered', 'accepted');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.account_role NOT NULL DEFAULT 'nurse', full_name text NOT NULL DEFAULT '', organization_name text, specialty text, home_state text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users read own profile" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id); CREATE POLICY "Users create own profile" ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id); CREATE POLICY "Users update own profile" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE TABLE public.hospitals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, name text NOT NULL, city text NOT NULL, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.hospitals TO authenticated; GRANT SELECT ON public.hospitals TO anon; GRANT ALL ON public.hospitals TO service_role; ALTER TABLE public.hospitals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published hospital directory" ON public.hospitals FOR SELECT TO anon, authenticated USING (true); CREATE POLICY "Hospital owners create" ON public.hospitals FOR INSERT TO authenticated WITH CHECK (auth.uid() = owner_id); CREATE POLICY "Hospital owners update" ON public.hospitals FOR UPDATE TO authenticated USING (auth.uid() = owner_id) WITH CHECK (auth.uid() = owner_id); CREATE POLICY "Hospital owners delete" ON public.hospitals FOR DELETE TO authenticated USING (auth.uid() = owner_id);
CREATE TABLE public.tourism_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, partner_name text NOT NULL, title text NOT NULL, category text NOT NULL, location text NOT NULL, description text NOT NULL DEFAULT '', retail_value numeric(10,2) NOT NULL DEFAULT 0, hospital_price numeric(10,2) NOT NULL DEFAULT 0, capacity integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tourism_offers TO authenticated; GRANT ALL ON public.tourism_offers TO service_role; ALTER TABLE public.tourism_offers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Hospital and tourism users view private offers" ON public.tourism_offers FOR SELECT TO authenticated USING ((SELECT role FROM public.profiles WHERE id = auth.uid()) IN ('hospital', 'tourism')); CREATE POLICY "Tourism owners create offers" ON public.tourism_offers FOR INSERT TO authenticated WITH CHECK (auth.uid() = owner_id AND (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'tourism'); CREATE POLICY "Tourism owners update offers" ON public.tourism_offers FOR UPDATE TO authenticated USING (auth.uid() = owner_id) WITH CHECK (auth.uid() = owner_id); CREATE POLICY "Tourism owners delete offers" ON public.tourism_offers FOR DELETE TO authenticated USING (auth.uid() = owner_id);
CREATE TABLE public.gigs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id uuid NOT NULL REFERENCES public.hospitals(id) ON DELETE CASCADE, owner_id uuid NOT NULL, title text NOT NULL, specialty text NOT NULL, city text NOT NULL, start_date date NOT NULL, duration_weeks integer NOT NULL DEFAULT 13, weekly_pay numeric(10,2) NOT NULL, shift text NOT NULL, status public.gig_status NOT NULL DEFAULT 'draft', description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.gigs TO authenticated; GRANT SELECT ON public.gigs TO anon; GRANT ALL ON public.gigs TO service_role; ALTER TABLE public.gigs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published gigs are public" ON public.gigs FOR SELECT TO anon, authenticated USING (status = 'published'); CREATE POLICY "Hospital owners read all gigs" ON public.gigs FOR SELECT TO authenticated USING (auth.uid() = owner_id); CREATE POLICY "Hospital owners create gigs" ON public.gigs FOR INSERT TO authenticated WITH CHECK (auth.uid() = owner_id AND (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'hospital'); CREATE POLICY "Hospital owners update gigs" ON public.gigs FOR UPDATE TO authenticated USING (auth.uid() = owner_id) WITH CHECK (auth.uid() = owner_id); CREATE POLICY "Hospital owners delete gigs" ON public.gigs FOR DELETE TO authenticated USING (auth.uid() = owner_id);
CREATE TABLE public.gig_offers (gig_id uuid NOT NULL REFERENCES public.gigs(id) ON DELETE CASCADE, offer_id uuid NOT NULL REFERENCES public.tourism_offers(id) ON DELETE CASCADE, added_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (gig_id, offer_id));
GRANT SELECT, INSERT, DELETE ON public.gig_offers TO authenticated; GRANT SELECT ON public.gig_offers TO anon; GRANT ALL ON public.gig_offers TO service_role; ALTER TABLE public.gig_offers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Package benefits on published gigs are public" ON public.gig_offers FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.gigs WHERE gigs.id = gig_id AND gigs.status = 'published')); CREATE POLICY "Hospital users add package benefits" ON public.gig_offers FOR INSERT TO authenticated WITH CHECK (auth.uid() = added_by AND (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'hospital'); CREATE POLICY "Hospital users remove package benefits" ON public.gig_offers FOR DELETE TO authenticated USING (auth.uid() = added_by);
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gig_id uuid NOT NULL REFERENCES public.gigs(id) ON DELETE CASCADE, nurse_id uuid NOT NULL, status public.application_status NOT NULL DEFAULT 'applied', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (gig_id, nurse_id));
GRANT SELECT, INSERT, UPDATE ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role; ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Nurses read own applications" ON public.applications FOR SELECT TO authenticated USING (auth.uid() = nurse_id); CREATE POLICY "Nurses apply" ON public.applications FOR INSERT TO authenticated WITH CHECK (auth.uid() = nurse_id AND (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'nurse'); CREATE POLICY "Hospitals read gig applications" ON public.applications FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.gigs WHERE gigs.id = gig_id AND gigs.owner_id = auth.uid())); CREATE POLICY "Hospitals advance applications" ON public.applications FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.gigs WHERE gigs.id = gig_id AND gigs.owner_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.gigs WHERE gigs.id = gig_id AND gigs.owner_id = auth.uid()));
CREATE TABLE public.qualification_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nurse_id uuid NOT NULL, step_key text NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'not_started', response jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (nurse_id, step_key));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.qualification_steps TO authenticated; GRANT ALL ON public.qualification_steps TO service_role; ALTER TABLE public.qualification_steps ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Nurses manage own qualification" ON public.qualification_steps FOR ALL TO authenticated USING (auth.uid() = nurse_id) WITH CHECK (auth.uid() = nurse_id); CREATE POLICY "Hospital users review applicant qualification" ON public.qualification_steps FOR SELECT TO authenticated USING ((SELECT role FROM public.profiles WHERE id = auth.uid()) = 'hospital' AND EXISTS (SELECT 1 FROM public.applications WHERE applications.nurse_id = qualification_steps.nurse_id));
CREATE INDEX gigs_status_city_idx ON public.gigs(status, city); CREATE INDEX tourism_offers_active_category_idx ON public.tourism_offers(active, category); CREATE INDEX applications_gig_idx ON public.applications(gig_id);
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, full_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name', '')) ON CONFLICT (id) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();